CREATE FUNCTION public.workspace_page(screen text DEFAULT 'Painel', term text DEFAULT '', active_filter text DEFAULT 'ativos', page_number integer DEFAULT 0, day_value date DEFAULT CURRENT_DATE, month_value date DEFAULT CURRENT_DATE, agenda_view text DEFAULT 'Dia') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid; medical boolean; result jsonb; start_at timestamptz; end_at timestamptz; month_start date; month_end date; patient_rows jsonb; appointment_rows jsonb; title_rows jsonb; encounter_rows jsonb; document_rows jsonb; settlement_rows jsonb; reversal_rows jsonb; BEGIN SELECT clinic_id,role='doctor' INTO c,medical FROM public.user_roles WHERE user_id=auth.uid(); IF c IS NULL OR NOT public.has_clinic_role(c) THEN RAISE EXCEPTION 'Acesso negado'; END IF; IF screen NOT IN ('Painel','Agenda','Pacientes','Atendimentos','Documentos','Financeiro','Configurações') OR page_number<0 OR page_number>100000 OR length(term)>200 THEN RAISE EXCEPTION 'Filtro inválido'; END IF; IF screen IN ('Atendimentos','Documentos','Configurações') AND NOT medical THEN RAISE EXCEPTION 'Acesso negado'; END IF;
month_start=date_trunc('month',month_value)::date; month_end=(month_start+interval '1 month')::date; start_at=day_value::timestamp AT TIME ZONE 'America/Sao_Paulo'; end_at=(day_value+1)::timestamp AT TIME ZONE 'America/Sao_Paulo'; IF screen='Agenda' AND agenda_view='Semana' THEN end_at=(day_value+7)::timestamp AT TIME ZONE 'America/Sao_Paulo'; ELSIF screen='Agenda' AND agenda_view='Mês' THEN start_at=date_trunc('month',day_value)::timestamp AT TIME ZONE 'America/Sao_Paulo'; end_at=(date_trunc('month',day_value)+interval '1 month')::timestamp AT TIME ZONE 'America/Sao_Paulo'; END IF;
SELECT coalesce(jsonb_agg(a),'[]'::jsonb) INTO appointment_rows FROM (SELECT * FROM public.appointments WHERE clinic_id=c AND screen IN ('Painel','Agenda') AND starts_at>=start_at AND starts_at<end_at ORDER BY starts_at,id LIMIT 50 OFFSET page_number*50) a;
SELECT coalesce(jsonb_agg(e),'[]'::jsonb) INTO encounter_rows FROM (SELECT id,clinic_id,patient_id,appointment_id,author_id,modality,status,version,created_at,updated_at,finalized_at,'{}'::jsonb AS content FROM public.encounters WHERE clinic_id=c AND screen='Atendimentos' AND medical ORDER BY created_at DESC,id LIMIT 50 OFFSET page_number*50) e;
SELECT coalesce(jsonb_agg(d),'[]'::jsonb) INTO document_rows FROM (SELECT id,clinic_id,patient_id,author_id,kind,status,storage_path,created_at,''::text AS content FROM public.documents WHERE clinic_id=c AND screen='Documentos' AND medical ORDER BY created_at DESC,id LIMIT 50 OFFSET page_number*50) d;
SELECT coalesce(jsonb_agg(t),'[]'::jsonb) INTO title_rows FROM (SELECT * FROM public.financial_titles WHERE clinic_id=c AND screen='Financeiro' AND due_date>=month_start AND due_date<month_end ORDER BY due_date,id LIMIT 50 OFFSET page_number*50) t;
SELECT coalesce(jsonb_agg(s),'[]'::jsonb) INTO settlement_rows FROM public.settlements s WHERE s.clinic_id=c AND s.title_id IN (SELECT (x->>'id')::uuid FROM jsonb_array_elements(title_rows) x);
SELECT coalesce(jsonb_agg(r),'[]'::jsonb) INTO reversal_rows FROM public.reversals r WHERE r.clinic_id=c AND r.settlement_id IN (SELECT (x->>'id')::uuid FROM jsonb_array_elements(settlement_rows) x);
SELECT coalesce(jsonb_agg(p),'[]'::jsonb) INTO patient_rows FROM (SELECT * FROM public.patients WHERE clinic_id=c AND ((screen='Pacientes' AND (active_filter='todos' OR active=(active_filter='ativos')) AND (name ILIKE '%'||term||'%' OR identifier ILIKE '%'||term||'%')) OR id IN (SELECT (x->>'patient_id')::uuid FROM jsonb_array_elements(appointment_rows||encounter_rows||document_rows) x)) ORDER BY name,id LIMIT 50 OFFSET CASE WHEN screen='Pacientes' THEN page_number*50 ELSE 0 END) p;
SELECT jsonb_build_object('membership',(SELECT to_jsonb(r) FROM public.user_roles r WHERE user_id=auth.uid()),'clinic',(SELECT to_jsonb(cl) FROM public.clinics cl WHERE id=c),'patients',patient_rows,'appointments',appointment_rows,'encounters',encounter_rows,'documents',document_rows,'titles',title_rows,'settlements',settlement_rows,'reversals',reversal_rows,'addenda','[]'::jsonb,'services',CASE WHEN screen='Configurações' THEN coalesce((SELECT jsonb_agg(s) FROM (SELECT * FROM public.services WHERE clinic_id=c ORDER BY name,id LIMIT 50 OFFSET page_number*50) s),'[]'::jsonb) ELSE '[]'::jsonb END,'doctors',(SELECT coalesce(jsonb_agg(d),'[]'::jsonb) FROM public.clinic_doctors(c) d),'total',CASE screen WHEN 'Pacientes' THEN (SELECT count(*) FROM public.patients WHERE clinic_id=c AND (active_filter='todos' OR active=(active_filter='ativos')) AND (name ILIKE '%'||term||'%' OR identifier ILIKE '%'||term||'%')) WHEN 'Agenda' THEN (SELECT count(*) FROM public.appointments WHERE clinic_id=c AND starts_at>=start_at AND starts_at<end_at) WHEN 'Atendimentos' THEN (SELECT count(*) FROM public.encounters WHERE clinic_id=c) WHEN 'Documentos' THEN (SELECT count(*) FROM public.documents WHERE clinic_id=c) WHEN 'Financeiro' THEN (SELECT count(*) FROM public.financial_titles WHERE clinic_id=c AND due_date>=month_start AND due_date<month_end) WHEN 'Configurações' THEN (SELECT count(*) FROM public.services WHERE clinic_id=c) ELSE (SELECT count(*) FROM public.appointments WHERE clinic_id=c AND starts_at>=start_at AND starts_at<end_at) END,'metrics',jsonb_build_object('today',(SELECT count(*) FROM public.appointments WHERE clinic_id=c AND NOT is_block AND starts_at>=start_at AND starts_at<end_at),'confirmed',(SELECT count(*) FROM public.appointments WHERE clinic_id=c AND NOT is_block AND status='confirmado' AND starts_at>=start_at AND starts_at<end_at),'completed',(SELECT count(*) FROM public.appointments WHERE clinic_id=c AND status='realizado' AND (starts_at AT TIME ZONE 'America/Sao_Paulo')::date>=month_start AND (starts_at AT TIME ZONE 'America/Sao_Paulo')::date<month_end),'documents',CASE WHEN medical THEN (SELECT count(*) FROM public.documents WHERE clinic_id=c) ELSE 0 END,'receipts',coalesce((SELECT sum(s.amount_cents) FROM public.settlements s JOIN public.financial_titles t ON t.id=s.title_id AND t.clinic_id=s.clinic_id WHERE s.clinic_id=c AND t.direction='receber' AND s.paid_at>=month_start AND s.paid_at<month_end),0),'expenses',coalesce((SELECT sum(s.amount_cents) FROM public.settlements s JOIN public.financial_titles t ON t.id=s.title_id AND t.clinic_id=s.clinic_id WHERE s.clinic_id=c AND t.direction='pagar' AND s.paid_at>=month_start AND s.paid_at<month_end),0),'reversal_net',coalesce((SELECT sum(CASE WHEN t.direction='receber' THEN r.amount_cents ELSE -r.amount_cents END) FROM public.reversals r JOIN public.settlements s ON s.id=r.settlement_id AND s.clinic_id=r.clinic_id JOIN public.financial_titles t ON t.id=s.title_id AND t.clinic_id=s.clinic_id WHERE r.clinic_id=c AND r.reversed_at>=month_start AND r.reversed_at<month_end),0),'open_receive',coalesce((SELECT sum(t.amount_cents-coalesce((SELECT sum(s.amount_cents) FROM public.settlements s WHERE s.title_id=t.id),0)+coalesce((SELECT sum(r.amount_cents) FROM public.reversals r JOIN public.settlements s ON s.id=r.settlement_id WHERE s.title_id=t.id),0)) FROM public.financial_titles t WHERE t.clinic_id=c AND t.direction='receber' AND NOT t.cancelled),0))) INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.workspace_page(text,text,text,integer,date,date,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.workspace_page(text,text,text,integer,date,date,text) TO authenticated;
CREATE FUNCTION public.search_patients(c uuid,term text DEFAULT '',page_number integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_clinic_role(c) OR page_number<0 OR length(term)>200 THEN RAISE EXCEPTION 'Acesso negado'; END IF; RETURN coalesce((SELECT jsonb_agg(p) FROM (SELECT id,name,identifier,birth_date,active FROM public.patients WHERE clinic_id=c AND active AND (name ILIKE '%'||term||'%' OR identifier ILIKE '%'||term||'%') ORDER BY name,id LIMIT 25 OFFSET page_number*25) p),'[]'::jsonb); END $$;
REVOKE ALL ON FUNCTION public.search_patients(uuid,text,integer) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.search_patients(uuid,text,integer) TO authenticated;